compile.workshop:
variables {
    global:
        127: __overpyTranslationHelper__
    player:
        127: __languageIndex__
}

rule ("Initialize global variables") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(__overpyTranslationHelper__, String Split(Custom String("0White0Blanc"), First Of(Null)));
    }
}

rule ("Initialize player variables") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Player Variable(Event Player, __languageIndex__, 1.1);
    }
}

rule ("translation player no detection") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Big Message(Event Player, Value In Array(String Split(Custom String("ＴＬＥｒｒHelloHello"), Global.__overpyTranslationHelper__), (Local Player).__languageIndex__));
    }
}

